import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { blogPosts, BlogPost } from '../blogs/index.generated';

import '../styles/pageStyles.css';

const groupBy = <T, K extends keyof any>(list: T[], getKey: (item: T) => K) =>
  list.reduce((groups, currentItem) => {
    const groupKey = getKey(currentItem);
    if (!groups[groupKey]) {
      groups[groupKey] = [];
    }
    groups[groupKey].push(currentItem);
    return groups;
  }, {} as Record<K, T[]>);

function groupAndSortByYear(posts: BlogPost[]) {
  const groupedPosts: Record<number, BlogPost[]> = groupBy(
    posts,
    (post) => new Date(post.date).getFullYear()
  );
  for (let key in groupedPosts) {
    groupedPosts[key].sort(
      (a, b) => new Date(b.date).getTime() - new Date(a.date).getTime()
    );
  }
  return groupedPosts;
}

function getPostYears(groupedPosts: Record<number, BlogPost[]>) {
  const years: number[] = [];
  for (let key in groupedPosts) {
    years.push(parseInt(key));
  }
  return years.sort((a, b) => b - a);
}

const formatDate = (date: string): string => {
  return new Date(date).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  });
};

const BlogListItem: React.FC<{ post: BlogPost; onClick: () => void }> = ({
  post,
  onClick,
}) => {
  return (
    <div className="container blogPostContainer" onClick={onClick} style={{ cursor: 'pointer' }}>
      <div className="blogPostTitle">
        <b>{post.title}</b>
      </div>
      <div className="blogPostDate">{formatDate(post.date)}</div>
      {post.summary && <div className="blogPostSummary">{post.summary}</div>}
    </div>
  );
};

const BlogPostView: React.FC<{ post: BlogPost; onBack: () => void }> = ({
  post,
  onBack,
}) => {
  const navigate = useNavigate();

  const handleBack = () => {
    navigate('/blog');
    onBack();
  };

  return (
    <div className="mainBody">
      <div className="pageContainer">
        <div className="blogFullPost">
          <button className="blogBackButton" onClick={handleBack}>
            &larr; Back to posts
          </button>
          <h1 className="blogFullPostTitle">{post.title}</h1>
          <div className="blogFullPostDate">{formatDate(post.date)}</div>
          <div className="blogFullPostContent">
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{post.content}</ReactMarkdown>
          </div>
        </div>
      </div>
    </div>
  );
};

const BlogYearSection: React.FC<{
  year: number;
  posts: BlogPost[];
  onSelectPost: (post: BlogPost) => void;
}> = ({ year, posts, onSelectPost }) => {
  return (
    <div key={year}>
      <h5 className="container blogYearHeader">{year}</h5>
      {posts.map((post) => (
        <BlogListItem key={post.slug} post={post} onClick={() => onSelectPost(post)} />
      ))}
    </div>
  );
};

const Blog: React.FC<{}> = () => {
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const [selectedPost, setSelectedPost] = useState<BlogPost | null>(null);
  const groupedByYearPosts = groupAndSortByYear(blogPosts);
  const postYears = getPostYears(groupedByYearPosts);

  useEffect(() => {
    if (slug) {
      const post = blogPosts.find((p) => p.slug === slug);
      if (post) {
        setSelectedPost(post);
      }
    } else {
      setSelectedPost(null);
    }
  }, [slug]);

  const handleSelectPost = (post: BlogPost) => {
    navigate(`/blog/${post.slug}`);
    setSelectedPost(post);
  };

  if (selectedPost) {
    return <BlogPostView post={selectedPost} onBack={() => setSelectedPost(null)} />;
  }

  return (
    <div className="mainBody">
      <div className="pageContainer">
        <h1 className="pageHeader">Blog</h1>
        {postYears.length > 0 ? (
          postYears.map((year) => (
            <BlogYearSection
              key={year}
              year={year}
              posts={groupedByYearPosts[year]}
              onSelectPost={handleSelectPost}
            />
          ))
        ) : (
          <div className="blogEmptyState">
            <p>No blog posts yet. Check back soon!</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Blog;
